__NUXT_JSONP__("/svet/stat/peru/jidlo", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q){return {data:[{tabsLoad:{tabWhatToSee:e,tabPrice:e,tabPeople:e,tabTrip:e,tabContact:e,tabHotel:e,tabNeighboring:k,tabVideos:h,tabArticles:h,tabWallSockets:i,tabChains:i,tabFauna:h,tabFlora:h,tabFoods:d,tabBrands:h},place:[{tld:".pe",name:"Peru",area:1285216,population:32971854,slug:l,id_continent:d,information_chatgpt:"\u003Cp\u003EPeru je země nacházející se v Jižní Americe. Je to země s bohatou historií a kulturou, kterou si turisté mohou prohlédnout v mnoha městech a archeologických nalezištích. Nejznámější atrakcí je pravděpodobně Machu Picchu, starověké město Inků, které je zapsáno na seznamu světového dědictví UNESCO a je jedním z nejnavštěvovanějších turistických míst v Jižní Americe.\u003C\u002Fp\u003E\n\u003Cp\u003EKromě Machu Picchu, turisté mohou navštívit také hlavní město Lima, které nabízí mnoho památek a trhů s místními suvenýry. V Cuscu, bývalém hlavním městě Inků, se turisté mohou procházet po kamenitých ulicích a navštívit mnoho historických budov, včetně katedrály a chrámů.\u003C\u002Fp\u003E\n\u003Cp\u003EPeru je rovněž známé svou vynikající kuchyní, která kombinuje prvky ze španělské, indiánské a africké kuchyně. Mezi oblíbená jídla patří ceviche, tradiční pokrm z ryb a mořských plodů, a lomo saltado, pokrm z masa a zeleniny, obvykle podávaný s rýží.\u003C\u002Fp\u003E\n\u003Cp\u003EPeru je také domovem mnoha přírodních divů, jako jsou například Amazonie, Andské hory a jezero Titicaca, nejvyšší jezero na světě, kde turisté mohou navštívit plovoucí ostrovy Uros a poznat tradiční život lidí, kteří zde žijí.\u003C\u002Fp\u003E\n\u003Cp\u003EPro turisty, kteří chtějí zažít dobrodružství, Peru nabízí mnoho možností pro turistiku, horolezectví a rafting. Turisté se mohou také věnovat surfování na plážích v oblasti Lima nebo pozorování dravců a kondorů v Národním parku Colca Canyon. \u003C\u002Fp\u003E\n\u003Cp\u003EPeru je země plná přírodních krás a kulturního dědictví, a pro turisty, kteří chtějí prozkoumat tuto zemi, je zde mnoho zajímavých míst k návštěvě a aktivit, které lze podniknout. \u003C\u002Fp",currency_code:"PEN",currency_name:"Peruánský sol",money_prices:[{name:"Taxi (cena za km)",value:2.5,date_update:c},{name:"Hlavní jídlo",value:30,date_update:c},{name:"Chleba",value:d,date_update:c},{name:"Mléko",value:m,date_update:c},{name:"Voda (500ml)",value:d,date_update:c},{name:"Espresso",value:i,date_update:c},{name:"Zmrzlina (jeden kopeček)",value:d,date_update:c},{name:"Pivo",value:8,date_update:c},{name:"Krabička cigaret",value:15,date_update:c},{name:"Bic Mac",value:a,date_update:c},{name:"Coca Cola (500ml)",value:i,date_update:c}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:"911",date_update:b},{name:"Policie",value:"105",date_update:b},{name:"Hasiči",value:"116",date_update:b},{name:"Zdravotnická záchranná služba",value:"117",date_update:b},{name:"Turistická policie",value:"0800-22221",date_update:b},{name:"Horská záchranná služba",value:"118",date_update:b},{name:"Pobřežní záchranná služba",value:"119",date_update:b}],phone_prefix:"+51",coordinates:[{latitude:"-9.189967",longitude:"-75.015152"}],people_religion:[{name:"Římskokatolické křesťanství",value:"76%",date_update:f},{name:"Evangeličtí křesťané",value:"14%",date_update:f},{name:"Jiná křesťanská vyznání",value:"6%",date_update:f},{name:"Nevěřící",value:n,date_update:f},{name:"Judaismus",value:o,date_update:f},{name:"Jiná náboženství",value:o,date_update:f}],people_nationality:[{name:"Mestici",value:"60%",date_update:g},{name:"Indiáni",value:"25%",date_update:g},{name:"Běloši",value:p,date_update:g},{name:"Afroperuánci",value:"3%",date_update:g},{name:"Asiaté",value:n,date_update:g},{name:"Ostatní",value:p,date_update:g}],visitors_entry:[{name:"Občanský průkaz",value:"Pro vstup do Peru je třeba mít platný cestovní doklad s fotografií. Občanský průkaz není platným cestovním dokladem pro vstup do země.",date_update:b},{name:"Cestovní pas",value:"Pro vstup do Peru je třeba mít platný cestovní pas. Občané České republiky mohou vstoupit do země s platným pasem bez nutnosti získání víza na pobyt do 183 dnů.",date_update:b},{name:"Vízum",value:"Pro občany České republiky není potřeba žádné vízum pro vstup do Peru na pobyt do 183 dnů. Při vstupu do země je nutné mít platný cestovní pas a předložit doklad o zpáteční letence nebo doklad o pokračujícím cestování.",date_update:b},{name:"Očkování",value:"Pro vstup do Peru nejsou povinné žádné očkování. Avšak je doporučeno očkování proti žloutence A a B, hepatitidě A a B, obrně, tyfu a žloutence typu B. V některých případech může být doporučeno i očkování proti žluté zimnici, pokud cestujete z oblasti, kde se tato nemoc vyskytuje.",date_update:b},{name:"Cestovní pojištění",value:"Pro vstup do Peru není vyžadováno povinné cestovní ani zdravotní pojištění. Nicméně, z důvodu nebezpečí krádeží a ztráty cestovních dokladů, se doporučuje mít sjednané cestovní pojištění, které pokryje náklady na případné lékařské ošetření, úrazy a krádeže během pobytu v zemi.",date_update:b},{name:"Bezpečností situace",value:"V Peru jsou určitá rizika z hlediska bezpečnosti a kriminality. Zvláštní opatrnost se doporučuje v oblasti hranic s Kolumbií a Ekvádorem, kde operují drogové gangy a teroristické organizace. Dále je potřeba být opatrný v centrálních částech měst Lima a Cusco, kde dochází ke krádežím a kapsářství. Při cestování mimo turistické oblasti je vhodné se dopředu informovat o bezpečnostní situaci v dané oblasti a necestovat v noci.",date_update:b},{name:"Další informace",value:"V Peru se setkáte s mnoha kulturními zvyklostmi, jako jsou tradiční tance, oblečení a gastronomie. Je vhodné respektovat místní kulturu a zvyky, zejména v případě návštěvy historických památek a kostelů. Dále je potřeba být opatrný při konzumaci vody a potravin, a preferovat balenou vodu a restaurace s dobrou hygienou.",date_update:b}],type_place:q,id_image_cover:j,id_image_hero:j,id_city_main:1708,affiliate:[{name:"booking",value:e}],mpz:"PE",alerts:a,zoom:[{google:m,booking:k}],ids_neighboring_countries:[{id:29},{id:31},{id:46},{id:49},{id:63}],organization:a,apps:a,links:a,information_author:a,seo_tags:a,language_phrases:a,wall_sockets:a,id:174,facts_place:a,created_at:"2023-12-27T16:33:10.517062+00:00",updated_at:"2023-12-27T17:07:31.480426+00:00",name_original:a}],imagePlace:[{id:j,name:l,source:"\u002Fworld\u002Fstates\u002F",type:q,author:"pixabay.com",created_at:"2023-05-03T20:14:00.749527+00:00",updated_at:"2023-12-27T20:42:18.520959+00:00"}],placeContinent:[{id:d,slug:"jizni-amerika",name:"Jižní Amerika",area:17840000,population:430000000,population_density:24.11,number_states:12,information_chatgpt:"\u003Cp\u003EJižní Amerika je kontinent nacházející se v jižní polovině zeměkoule. Je druhým největším kontinentem v Americe a čtvrtým největším kontinentem na světě. Rozprostírá se od Karibiku na severu po Průliv Drakea na jihu, což představuje přibližně 7 000 kilometrů. Tento kontinent obývá více než 420 milionů lidí a skládá se ze 12 různých států.\u003C\u002Fp\u003E\n\u003Cp\u003EJižní Amerika má velmi rozmanitou geografii. Na západní straně kontinentu se nachází Andské pohoří, které je nejdelší pohoří na světě a táhne se přes 7 zemí. Na východní straně se nachází rozsáhlé deštné pralesy a oblasti savan. Kromě toho se zde nachází také největší řeka na světě - Amazonka, která má neuvěřitelný vliv na floru a faunu regionu.\u003C\u002Fp\u003E\n\u003Cp\u003EJižní Amerika má také velmi bohatou historii a kulturu. Před příchodem Evropanů byla tato oblast domovem mnoha starověkých civilizací, jako jsou Inkové, Mayové a Aztékové. Tyto civilizace zanechaly pozoruhodné památky, jako jsou Machu Picchu, Chichén Itzá a Tiahuanaco. Později byla tato oblast ovlivněna kolonizací ze strany Španělska a Portugalska, což má dodnes vliv na jazyky, kulturu a způsob života.\u003C\u002Fp\u003E\n\u003Cp\u003EJižní Amerika je také velmi oblíbenou turistickou destinací. V Argentině a Brazílii se nacházejí největší vodopády světa - Iguazú a Niagarské vodopády. Peru je domovem Machu Picchu, jedné z nejnavštěvovanějších archeologických lokalit na světě. Kromě toho jsou zde také krásné pláže, horské túry, národní parky a další přírodní krásy.\u003C\u002Fp\u003E\n\u003Cp\u003EV Jižní Americe se také nachází mnoho kulturních festivalů a událostí. Například karnevaly v Rio de Janeiru a Buenos Aires jsou světoznámé pro svou atmosféru a pestrost barev. Také zde můžete ochutnat mnoho unikátních kulinářských specialit, jako jsou arepas v Kolumbii, ceviche v Peru a asado v Argentině.\u003C\u002Fp\u003E\n\u003Cp\u003EZkrátka, Jižní Amerika je kontinent plnýkrás, kulturního bohatství a přírodních divů. Mnoho turistů sem přijíždí za poznáním exotického prostředí, ale také kvůli možnostem dobrodružství a sportovních aktivit. Například v Brazílii je oblíbená plážová fotbalová hra zvaná futevôlei, zatímco v Chile si turisté užívají snowboardování na Andách.\u003C\u002Fp\u003E\n\u003Cp\u003EJižní Amerika má také své problémy, jako je sociální nerovnost, kriminalita a korupce. Některé oblasti jsou považovány za nebezpečné pro turisty, takže je třeba být obezřetní a využívat služby kvalitních turistických průvodců.\u003C\u002Fp\u003E\n\u003Cp\u003EZávěrem lze říci, že Jižní Amerika je fascinující kontinent, který nabízí mnoho příležitostí pro poznání, zážitky a dobrodružství. Bez ohledu na to, jestli plánujete návštěvu kvůli přírodě, kultuře nebo jen na odpočinek na pláži, určitě nebudete zklamáni.\u003C\u002Fp\u003E",coordinates:[{latitude:-14.235004,longitude:-51.92528}],type_place:"continent",id_image_cover:d,id_image_hero:d,zoom:[{google:d,booking:i}],information_author:a,seo_tags:a,created_at:"2023-12-27T16:35:37.460505+00:00",updated_at:"2023-12-27T17:07:06.531847+00:00",name_original:a}]}],fetch:{"OrganismsoSidebarListComponent:0":{events:[],images:a}},mutations:[]}}(null,"05-2023","09-2021",2,true,"01-2021","04-2023",0,3,341,5,"peru",4,"2%","1%","5%","state")));